import assert from 'node:assert/strict';
import {M,H,aggregate5m,entryFor,simulate,summarize,auditedActual,mergeWindows,blockBootstrap,matureCohort,returnDirection} from './research-pump-turn-near-20261028.mjs';
for(const value of [null,undefined,NaN,Infinity,'0'])assert.equal(returnDirection(value),'UNKNOWN','missing/non-numeric return must not become UP');
assert.equal(returnDirection(0),'UP');assert.equal(returnDirection(1),'UP');assert.equal(returnDirection(-1),'DOWN');
const rows=()=>Array.from({length:500},(_,i)=>({t:i*M,end:(i+1)*M-1,o:100,h:100.2,l:99.8,c:100,q:40000,v:400,buy:16000}));
const event={id:'e',symbol:'XUSDT',observedAt:10*M+12345,livePrice:100,zoneHigh:99.8,peak:110,baseline:100000};
let r=rows();
assert.equal(entryFor(event,r).t,11*M,'first full future minute only');
assert.equal(entryFor({...event,observedAt:10*M},r).t,11*M,'exact minute boundary still waits for the next minute');
r[10].h=150;r[10].l=50;
assert.equal(simulate(event,r,500*M).status,'TIMEOUT','do not use high/low before event within its minute');
r[11].h=107;r[11].l=97;
let trade=simulate(event,r,500*M);assert.equal(trade.status,'SL');assert.equal(trade.ambiguous,true);assert.ok(trade.netRoe5x< -30);
r=rows();r[12].l=97;trade=simulate(event,r,500*M);assert.equal(trade.status,'TP');assert.ok(Math.abs(trade.netRoe5x-9.3)<1e-9);
assert.equal(simulate(event,rows().slice(0,30),30*M).status,'CENSORED');
assert.equal(simulate(event,rows().slice(0,11),event.observedAt).status,'CENSORED_NO_ENTRY_BAR');
assert.equal(simulate(event,rows().slice(0,20),20*M,'wait_red_5m').status,'CONFIRMATION_CENSORED');
assert.equal(simulate(event,rows(),500*M,'wait_red_5m').status,'NO_CONFIRMATION');
r=rows();for(let i=10;i<15;i++){r[i].c=99.6;r[i].l=99.4;}r[14].c=99.5;
assert.equal(entryFor(event,r,'wait_red_5m').t,15*M,'cannot enter until confirmation candle closes');
assert.equal(entryFor(event,r,'wait_full_5m').t,15*M);
assert.equal(entryFor({...event,baseline:200000},r,'wait_full_5m'),null,'volume gate actually applied');
assert.equal(aggregate5m(r.slice(1,5)).length,0,'partial five-minute candle excluded');
assert.equal(aggregate5m(r.slice(0,5)).length,1);
const base=simulate(event,r,500*M),mutated=r.map(b=>b.t<event.observedAt?b:{...b,h:b.h*2});
assert.equal(entryFor(event,mutated).t,entryFor(event,r).t,'immediate timing independent of outcome');
const record={symbol:'XUSDT',observedAt:event.observedAt,results:{immediate:base}};
assert.equal(summarize([record]).n,1);assert.equal(blockBootstrap([record],20).blocks,1);
assert.equal(matureCohort([record],100*M).length,0,'exclude recent quick wins as well as unresolved losses');
assert.equal(matureCohort([record],500*M).length,1,'maturity selected by clock, independently of PnL');
assert.deepEqual(mergeWindows([[5,8],[0,2],[1,6],[10,11]]),[[0,8],[10,11]]);
const a={symbol:'XUSDT',orderId:'1',clientOrderId:'ptns_1'};
const filled={...a,signalSource:'pump-turn-near-short',direction:'SHORT',positionStatus:'CLOSED',closeGroupId:'g',isDca:false,netRealizedPnlUsdt:1,realizedRoePct:50};
assert.equal(auditedActual({fills:{a:{record:filled}}},{attempts:{a}}).trades.length,1);
assert.equal(auditedActual({fills:{a:{record:filled},b:{record:{...filled,orderId:'2',isDca:true}}}},{attempts:{a}}).trades.length,0,'exclude shared DCA close-group contamination');
assert.equal(auditedActual({fills:{a:{record:filled}}},{attempts:{}}).trades.length,0,'require exact native submission attribution');
console.log('PASS: causal, TP/SL, right-censoring, confirmation, aggregation, mature-cohort, statistics and exact-fill attribution checks.');
